916→        track.className = 'bar-track';
917→        const fill = document.createElement('div');
918→        fill.className = 'bar-fill';
919→        fill.style.width = (p.count / maxCount) * 100 + '%';
920→        fill.style.background = '#8b5cf6';
921→        track.appendChild(fill);
