849→  <script>
850→    function toggleCollapsible(header) {
851→      header.classList.toggle('open');
852→      const content = header.nextElementSibling;
853→      content.classList.toggle('open');
854→    }
855→    function copyText(btn) {
856→      const code = btn.previousElementSibling;
857→      navigator.clipboard.writeText(code.textContent).then(() => {
858→        btn.textContent = 'Copied!';
859→        setTimeout(() => { btn.textContent = 'Copy'; }, 2000);
860→      });
861→    }
862→    function copyCmdItem(idx) {
863→      const checkbox = document.getElementById('cmd-' + idx);
864→      if (checkbox) {
865→        const text = checkbox.dataset.text;
866→        navigator.clipboard.writeText(text).then(() => {
867→          const btn = checkbox.nextElementSibling.querySelector('.copy-btn');
868→          if (btn) { btn.textContent = 'Copied!'; setTimeout(() => { btn.textContent = 'Copy'; }, 2000); }
869→        });
870→      }
871→    }
872→    function copyAllCheckedClaudeMd() {
873→      const checkboxes = document.querySelectorAll('.cmd-checkbox:checked');
874→      const texts = [];
875→      checkboxes.forEach(cb => {
876→        if (cb.dataset.text) { texts.push(cb.dataset.text); }
877→      });
878→      const combined = texts.join('\n');
879→      const btn = document.querySelector('.copy-all-btn');
880→      if (btn) {
881→        navigator.clipboard.writeText(combined).then(() => {
882→          btn.textContent = 'Copied ' + texts.length + ' items!';
883→          btn.classList.add('copied');
884→          setTimeout(() => { btn.textContent = 'Copy All Checked'; btn.classList.remove('copied'); }, 2000);
885→        });
886→      }
887→    }
888→    // Timezone selector for time of day chart (data is from our own analytics, not user input)
889→    const rawHourCounts = {"0":77,"1":60,"2":8,"7":1,"8":10,"9":14,"10":23,"11":24,"12":11,"13":17,"14":21,"15":13,"16":30,"17":12,"18":19,"19":3,"20":1,"21":18,"22":36,"23":61};
890→    function updateHourHistogram(offsetFromPT) {
891→      const periods = [
892→        { label: "Morning (6-12)", range: [6,7,8,9,10,11] },
893→        { label: "Afternoon (12-18)", range: [12,13,14,15,16,17] },
894→        { label: "Evening (18-24)", range: [18,19,20,21,22,23] },
895→        { label: "Night (0-6)", range: [0,1,2,3,4,5] }
896→      ];
897→      const adjustedCounts = {};
898→      for (const [hour, count] of Object.entries(rawHourCounts)) {
899→        const newHour = (parseInt(hour) + offsetFromPT + 24) % 24;
900→        adjustedCounts[newHour] = (adjustedCounts[newHour] || 0) + count;
901→      }
902→      const periodCounts = periods.map(p => ({
903→        label: p.label,
904→        count: p.range.reduce((sum, h) => sum + (adjustedCounts[h] || 0), 0)
905→      }));
906→      const maxCount = Math.max(...periodCounts.map(p => p.count)) || 1;
907→      const container = document.getElementById('hour-histogram');
908→      container.textContent = '';
909→      periodCounts.forEach(p => {
910→        const row = document.createElement('div');
911→        row.className = 'bar-row';
912→        const label = document.createElement('div');
913→        label.className = 'bar-label';
914→        label.textContent = p.label;
915→        const track = document.createElement('div');
916→        track.className = 'bar-track';
917→        const fill = document.createElement('div');
918→        fill.className = 'bar-fill';
919→        fill.style.width = (p.count / maxCount) * 100 + '%';
920→        fill.style.background = '#8b5cf6';
921→        track.appendChild(fill);
922→        const value = document.createElement('div');
923→        value.className = 'bar-value';
924→        value.textContent = p.count;
925→        row.appendChild(label);
926→        row.appendChild(track);
927→        row.appendChild(value);
928→        container.appendChild(row);
929→      });
930→    }
931→    document.getElementById('timezone-select').addEventListener('change', function() {
932→      const customInput = document.getElementById('custom-offset');
933→      if (this.value === 'custom') {
934→        customInput.style.display = 'inline-block';
935→        customInput.focus();
936→      } else {
937→        customInput.style.display = 'none';
938→        updateHourHistogram(parseInt(this.value));
939→      }
940→    });
941→    document.getElementById('custom-offset').addEventListener('change', function() {
942→      const offset = parseInt(this.value) + 8;
943→      updateHourHistogram(offset);
944→    });
