from cohezion.compound.coherence_config import CoherenceConfig, DEFAULT_CONFIG


class TestCoherenceConfig:
    """Verify Charter-aligned defaults and HIHO stability checks."""

    def test_default_hiho_target(self) -> None:
        assert DEFAULT_CONFIG.hiho_target == 0.5

    def test_default_hiho_band(self) -> None:
        assert DEFAULT_CONFIG.hiho_band_min == 0.4
        assert DEFAULT_CONFIG.hiho_band_max == 0.6

    def test_is_hiho_stable_at_target(self) -> None:
        assert DEFAULT_CONFIG.is_hiho_stable(0.5) is True

    def test_is_hiho_stable_at_boundaries(self) -> None:
        assert DEFAULT_CONFIG.is_hiho_stable(0.4) is True
        assert DEFAULT_CONFIG.is_hiho_stable(0.6) is True

    def test_is_hiho_unstable_outside_band(self) -> None:
        assert DEFAULT_CONFIG.is_hiho_stable(0.39) is False
        assert DEFAULT_CONFIG.is_hiho_stable(0.61) is False
        assert DEFAULT_CONFIG.is_hiho_stable(0.0) is False
        assert DEFAULT_CONFIG.is_hiho_stable(1.0) is False

    def test_degradation_coherence_within_hiho_band(self) -> None:
        assert DEFAULT_CONFIG.degradation_coherence <= DEFAULT_CONFIG.hiho_band_min

    def test_inflection_below_degradation(self) -> None:
        assert DEFAULT_CONFIG.inflection_coherence < DEFAULT_CONFIG.degradation_coherence

    def test_alignment_weights_sum_to_one(self) -> None:
        total = (
            DEFAULT_CONFIG.alignment_intent_weight
            + DEFAULT_CONFIG.alignment_constraint_weight
            + DEFAULT_CONFIG.alignment_criteria_weight
        )
        assert abs(total - 1.0) < 1e-9

    def test_frozen_dataclass(self) -> None:
        try:
            DEFAULT_CONFIG.hiho_target = 0.9  # type: ignore[misc]
            raise AssertionError("Should have raised FrozenInstanceError")
        except AttributeError:
            pass

